.btn-danger:hover {
    -fx-background-color: linear-gradient(to right, #dc2626, #b91c1c);
    -fx-effect: dropshadow(gaussian, rgba(239, 68, 68, 0.4), 12, 0.0, 0, 4);
}

.btn-danger:pressed {
    -fx-opacity: 0.85;
}

.icon-button {
    -fx-min-width: 44;
    -fx-min-height: 44;
    -fx-pref-width: 44;
    -fx-pref-height: 44;
    -fx-padding: 0;
    -fx-background-radius: 12;
    -fx-border-radius: 12;
    -fx-font-size: 18px;
    -fx-alignment: center;
}

.admin-actions-panel .button {
    -fx-background-color: rgba(148, 163, 184, 0.14);
    -fx-text-fill: #e7edf8;
    -fx-background-radius: 9;
    -fx-border-color: rgba(99, 179, 255, 0.20);
    -fx-border-radius: 9;
    -fx-cursor: hand;
}

.admin-actions-panel .button:hover {
    -fx-background-color: rgba(99, 179, 255, 0.25);
}

.admin-list {
    -fx-background-color: rgba(10, 18, 34, 0.92);
    -fx-background-radius: 10;
}

.text-field,
.password-field,
.combo-box,
.date-picker,
.text-area,
.menu-button,
.table-view,
.list-view {
    -fx-background-color: rgba(10, 18, 34, 0.95);
    -fx-text-fill: #e7edf8;
    -fx-border-color: rgba(148, 163, 184, 0.26);
    -fx-border-radius: 8;
    -fx-background-radius: 8;
}

.button,
.hyperlink {
    -fx-text-fill: #e7edf8;
}

.table-row-cell .table-cell.etat-en-cours {
    -fx-text-fill: #facc15;
    -fx-font-weight: 700;
}

.table-row-cell .table-cell.etat-resolu {
    -fx-text-fill: #22c55e;
    -fx-font-weight: 700;
}

.table-row-cell .table-cell.etat-rejete {
    -fx-text-fill: #ef4444;
    -fx-font-weight: 700;
}

.punition-cards-panel {
    -fx-background-color: transparent;
}

.punition-player-card {
    -fx-padding: 10;
    -fx-background-radius: 12;
    -fx-border-radius: 12;
    -fx-border-color: rgba(56, 189, 248, 0.22);
}

.punition-item-card {
    -fx-padding: 12;
    -fx-background-radius: 12;
    -fx-border-radius: 12;
    -fx-border-color: rgba(56, 189, 248, 0.22);
}

.punition-meta-row {
    -fx-spacing: 10;
    -fx-alignment: center-left;
}

.punition-status-badge {
    -fx-border-color: rgba(148, 163, 184, 0.45);
}

.punition-date-range {
    -fx-spacing: 8;
    -fx-alignment: center-left;
}

.punition-date-chip {
    -fx-padding: 6 10 6 10;
    -fx-background-radius: 999;
    -fx-border-radius: 999;
    -fx-background-color: rgba(37, 99, 235, 0.2);
    -fx-border-color: rgba(96, 165, 250, 0.45);
    -fx-text-fill: #bfdbfe;
    -fx-font-weight: 700;
}

.punition-ban-count {
    -fx-text-fill: #a5f3fc;
    -fx-font-weight: 700;
}

.reclamation-cards-panel {
    -fx-background-color: transparent;
}

.reclamation-item-card {
    -fx-padding: 12;
    -fx-background-radius: 12;
    -fx-border-radius: 12;
    -fx-border-color: rgba(56, 189, 248, 0.22);
}

.reclamation-meta-row {
    -fx-spacing: 12;
}

.reclamation-meta-badge {
    -fx-padding: 5 10 5 10;
    -fx-background-radius: 999;
    -fx-border-radius: 999;
    -fx-border-width: 1;
    -fx-font-weight: 700;
}

.reclamation-meta-type {
    -fx-background-color: rgba(59, 130, 246, 0.2);
    -fx-text-fill: #93c5fd;
    -fx-border-color: rgba(59, 130, 246, 0.45);
}

.reclamation-meta-player {
    -fx-background-color: rgba(20, 184, 166, 0.2);
    -fx-text-fill: #99f6e4;
    -fx-border-color: rgba(20, 184, 166, 0.45);
}

.reclamation-meta-etat-en-cours {
    -fx-background-color: rgba(250, 204, 21, 0.18);
    -fx-text-fill: #facc15;
    -fx-border-color: rgba(250, 204, 21, 0.45);
}

.reclamation-meta-etat-resolu {
    -fx-background-color: rgba(34, 197, 94, 0.2);
    -fx-text-fill: #4ade80;
    -fx-border-color: rgba(34, 197, 94, 0.45);
}

.reclamation-meta-etat-rejete {
    -fx-background-color: rgba(239, 68, 68, 0.2);
    -fx-text-fill: #f87171;
    -fx-border-color: rgba(239, 68, 68, 0.45);
}

.admin-response-cards-panel {
    -fx-background-color: transparent;
}

.admin-response-item-card {
    -fx-padding: 12;
    -fx-background-radius: 12;
    -fx-border-radius: 12;
    -fx-border-color: rgba(56, 189, 248, 0.22);
}

.admin-response-meta-row {
    -fx-spacing: 10;
    -fx-alignment: center-left;
}

.card-focus-highlight {
    -fx-border-color: #60a5fa;
    -fx-border-width: 2;
    -fx-effect: dropshadow(gaussian, rgba(96, 165, 250, 0.55), 20, 0.15, 0, 0);
}


/* Chatbot floating button and messages */
.chatbot-button {
    -fx-font-size: 20px;
    -fx-min-width: 56;
    -fx-min-height: 56;
    -fx-background-radius: 999;
    -fx-background-color: linear-gradient(to right, #06b6d4, #7c3aed);
    -fx-text-fill: white;
    -fx-effect: dropshadow(gaussian, rgba(124, 58, 237, 0.35), 12, 0.0, 0, 4);
}

.chatbot-message {
    -fx-padding: 8 10 8 10;
    -fx-background-radius: 8;
}

.chatbot-message.user {
    -fx-background-color: linear-gradient(to right, #60a5fa, #a78bfa);
    -fx-text-fill: #021124;
}

.chatbot-message.bot {
    -fx-background-color: rgba(255,255,255,0.04);
    -fx-text-fill: #dbeafe;
}
